description:
Write `final class Fetcher` with:

```java
static CompletableFuture<Map<Integer, String>> fetchAll(List<Integer> ids, Function<Integer, CompletableFuture<String>> fetch)
```

- start every fetch at once, before waiting for any (call `fetch` for each id in the list order);
- the returned future completes once every fetch has finished, with a `TreeMap` from id to result;
- a fetch that fails maps to `"error: " + the message of the original exception` (not the `CompletionException` around it), and one that throws straight away (instead of returning a failed future) is treated the same;
- a failure never makes the whole result fail, and the method never blocks.

starter.Fetcher.java:
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public final class Fetcher {
    public static CompletableFuture<Map<Integer, String>> fetchAll(List<Integer> ids, Function<Integer, CompletableFuture<String>> fetch) {
        Map<Integer, String> out = new TreeMap<>();
        for (int id : ids) out.put(id, fetch.apply(id).join());
        return CompletableFuture.completedFuture(out);
    }
}

solution.Fetcher.java:
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public final class Fetcher {
    public static CompletableFuture<Map<Integer, String>> fetchAll(List<Integer> ids, Function<Integer, CompletableFuture<String>> fetch) {
        Map<Integer, CompletableFuture<String>> running = new LinkedHashMap<>();
        for (int id : ids) {
            CompletableFuture<String> f;
            try {
                f = fetch.apply(id);
            } catch (RuntimeException e) {
                f = CompletableFuture.failedFuture(e);
            }
            running.put(id, f.handle((value, error) -> {
                if (error == null) return value;
                Throwable cause = error instanceof CompletionException && error.getCause() != null ? error.getCause() : error;
                return "error: " + cause.getMessage();
            }));
        }
        return CompletableFuture.allOf(running.values().toArray(new CompletableFuture[0]))
                .thenApply(ignored -> {
                    Map<Integer, String> out = new TreeMap<>();
                    running.forEach((id, f) -> out.put(id, f.join()));
                    return out;
                });
    }
}

unitTests:
test("every id has a result, failures included", () -> {
    Map<Integer, CompletableFuture<String>> pending = new HashMap<>();
    Function<Integer, CompletableFuture<String>> fetch = id -> {
        if (id == 9) throw new IllegalArgumentException("bad id");
        var f = new CompletableFuture<String>();
        pending.put(id, f);
        return f;
    };
    var result = Fetcher.fetchAll(List.of(4, 1, 2, 9), fetch);
    checkEq(pending.keySet(), Set.of(4, 1, 2));
    check(!result.isDone(), "must not finish before the fetches");
    pending.get(2).completeExceptionally(new IllegalStateException("not found"));
    pending.get(4).complete("user4");
    check(!result.isDone());
    pending.get(1).complete("user1");
    checkEq(result.join().toString(), "{1=user1, 2=error: not found, 4=user4, 9=error: bad id}");
});

test("all fetches start before any finishes", () -> {
    List<Integer> started = new ArrayList<>();
    Function<Integer, CompletableFuture<String>> fetch = id -> {
        started.add(id);
        return new CompletableFuture<>();
    };
    Fetcher.fetchAll(List.of(3, 1, 2), fetch);
    checkEq(started, List.of(3, 1, 2));
});

test("nothing to fetch", () -> {
    checkEq(Fetcher.fetchAll(List.of(), id -> null).join().size(), 0);
});

